-- Nội dung chi tiết cho 50 sản phẩm mẫu: mô tả ngắn, giới thiệu (HTML: p, h3, ul) và thông số bổ sung. Chạy sau product-2.sql.
SET NAMES utf8mb4;
UPDATE product_details SET description = 'Nồi 6 lít đủ chiên nguyên con gà 1,5 kg, điều khiển và hẹn giờ ngay trên điện thoại.', content = '<p>SmartCook 6L dành cho nhà đông người hoặc hay nấu một lần cho cả bữa. Lòng nồi rộng, đặt vừa gà nguyên con hay hai lớp khoai tây mà không phải chia mẻ.</p><h3>Điểm nổi bật</h3><ul><li>Công suất 1500W, khí nóng đối lưu làm chín đều cả mặt dưới, không cần lật nhiều lần</li><li>Kết nối Wi‑Fi: chọn chế độ, hẹn giờ và nhận nhắc lật món trên app</li><li>12 chế độ cài sẵn cho gà, cá, khoai, bánh, rã đông</li><li>Lòng nồi chống dính tháo rời, rửa được bằng máy rửa bát</li></ul><h3>Phù hợp với</h3><p>Gia đình 4–6 người, người bận rộn muốn hẹn giờ nấu trước khi về nhà.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"programs": "12 chế độ", "control": "Cảm ứng + app Wi‑Fi"}') WHERE product_id = 1;
UPDATE product_details SET description = 'Công nghệ Rapid Air của Philips: khoai giòn đều, giảm tới 90% lượng dầu so với chiên ngập.', content = '<p>HD9252 là mẫu nồi chiên gọn gàng cho căn bếp nhỏ. Rổ 4,1 lít nấu vừa bữa cho 2–3 người, máy làm nóng nhanh nên không cần làm nóng trước.</p><h3>Điểm nổi bật</h3><ul><li>Luồng khí Rapid Air thổi xoáy giúp thực phẩm chín đều, vỏ giòn mà bên trong vẫn mềm</li><li>Núm vặn chỉnh nhiệt và hẹn giờ đơn giản, người lớn tuổi cũng dùng được ngay</li><li>Rổ và khay có lớp chống dính, rửa được bằng máy</li><li>Ứng dụng NutriU có hàng trăm công thức gợi ý theo đúng dòng máy</li></ul><h3>Phù hợp với</h3><p>Cặp đôi, gia đình nhỏ, căn hộ có mặt bếp hẹp.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"programs": "Chỉnh tay nhiệt độ và giờ", "control": "Núm vặn"}') WHERE product_id = 2;
UPDATE product_details SET description = 'Nồi 5,5 lít bảng cảm ứng, 8 chế độ nấu sẵn, giá dễ chịu cho gia đình Việt.', content = '<p>Sunhouse Mama 5.5L cân bằng giữa dung tích và giá. Bảng điện tử hiển thị rõ nhiệt độ, thời gian, chỉ cần chạm một lần là chọn đúng món.</p><h3>Điểm nổi bật</h3><ul><li>Công suất 1700W làm nóng nhanh, nấu gà, sườn, cá đều trong 15–25 phút</li><li>8 chế độ cài sẵn, có rã đông và hâm nóng</li><li>Lòng nồi chống dính an toàn, tay cầm cách nhiệt</li><li>Tự ngắt khi rút khay, không lo quên tắt</li></ul><h3>Phù hợp với</h3><p>Gia đình 3–5 người muốn mẫu điện tử dễ dùng trong tầm giá phổ thông.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"programs": "8 chế độ", "control": "Cảm ứng"}') WHERE product_id = 3;
UPDATE product_details SET description = 'Lò vi sóng 20 lít bảng điều khiển tiếng Việt: hâm cơm, rã đông thịt chỉ với vài nút bấm.', content = '<p>Sharp 20L làm tốt những việc bếp nhà dùng mỗi ngày: hâm nóng thức ăn thừa, rã đông thịt cá, nấu nhanh món đơn giản. Khoang 20 lít vừa đĩa cơm lớn.</p><h3>Điểm nổi bật</h3><ul><li>Công suất vi sóng 800W, hâm một bát canh chỉ khoảng 2 phút</li><li>Rã đông theo trọng lượng, thịt mềm đều mà không chín mép</li><li>Bảng điều khiển điện tử có chữ tiếng Việt, khoá trẻ em</li><li>Kích thước gọn, đặt vừa nóc tủ lạnh hoặc kệ bếp</li></ul><h3>Phù hợp với</h3><p>Sinh viên, người đi làm, gia đình nhỏ cần lò cơ bản bền bỉ.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"control": "Điện tử, tiếng Việt", "programs": "Hâm, rã đông, nấu nhanh"}') WHERE product_id = 4;
UPDATE product_details SET description = 'Khoang tráng men gốm chống xước, lau sạch dầu mỡ chỉ bằng khăn ẩm.', content = '<p>Samsung 23L có lớp men Ceramic bên trong khoang lò: không gỉ, kháng khuẩn và rất dễ vệ sinh. Dung tích 23 lít đủ hâm đĩa lớn hoặc bát tô cho cả nhà.</p><h3>Điểm nổi bật</h3><ul><li>Men gốm Ceramic bền hơn thép sơn, không bong tróc theo thời gian</li><li>Chế độ rã đông nhanh và hâm nóng tự động theo món</li><li>Mặt kính đen sang trọng, hợp nhiều kiểu bếp</li><li>Khử mùi khoang lò bằng chế độ Deodorization</li></ul><h3>Phù hợp với</h3><p>Gia đình 3–5 người, người ngại vệ sinh lò sau khi hâm đồ nhiều dầu.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"control": "Điện tử", "programs": "Hâm, rã đông, khử mùi"}') WHERE product_id = 5;
UPDATE product_details SET description = 'Quạt đứng Mitsubishi động cơ bạc đạn, chạy êm và bền nhiều năm.', content = '<p>LV16-RV là mẫu quạt đứng quen thuộc của nhiều gia đình nhờ độ bền. Động cơ bạc đạn ít nóng, chạy cả đêm vẫn êm, kèm remote để chỉnh ngay từ giường.</p><h3>Điểm nổi bật</h3><ul><li>3 tốc độ gió cùng chế độ gió tự nhiên, gió ngủ dịu nhẹ</li><li>Hẹn giờ tắt tối đa 7,5 giờ, tiết kiệm điện ban đêm</li><li>Công suất chỉ 47W, chạy 8 tiếng mỗi ngày tốn khoảng 11 kWh mỗi tháng</li><li>Điều chỉnh chiều cao và góc nghiêng linh hoạt</li></ul><h3>Phù hợp với</h3><p>Phòng ngủ, phòng khách nhỏ, người cần quạt bền để dùng lâu dài.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"timer": "7,5 giờ", "control": "Remote"}') WHERE product_id = 6;
UPDATE product_details SET description = 'Vừa là quạt, vừa là máy lọc không khí: lọc bụi mịn và mát cả phòng mà không có cánh quạt.', content = '<p>Dyson Purifier Cool kết hợp quạt không cánh với bộ lọc HEPA kín. Máy tự đo chất lượng không khí và hiển thị chỉ số trên màn hình, thay vì phải mua hai thiết bị riêng.</p><h3>Điểm nổi bật</h3><ul><li>Bộ lọc HEPA H13 giữ lại bụi mịn PM2.5, phấn hoa, lông thú</li><li>Không có cánh quạt lộ ra ngoài, an toàn cho trẻ nhỏ và thú cưng</li><li>Cảm biến tự động tăng giảm tốc độ theo mức ô nhiễm</li><li>Chế độ đêm chạy êm khoảng 35dB, đèn màn hình tự mờ</li><li>Điều khiển và xem lịch sử chất lượng không khí trên app MyDyson</li></ul><h3>Phù hợp với</h3><p>Gia đình có trẻ nhỏ, người bị viêm mũi dị ứng, căn hộ ở khu nhiều bụi.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"filter": "HEPA H13 + than hoạt tính", "connectivity": "Wi‑Fi, app MyDyson"}') WHERE product_id = 7;
UPDATE product_details SET description = 'Quạt trần 5 cánh gió mạnh và êm, điều khiển từ xa, có cảm biến nhiệt tự chỉnh tốc độ.', content = '<p>Panasonic 5 cánh phù hợp phòng khách trần cao. Gió toả đều khắp phòng thay vì chỉ thổi một hướng, lại không chiếm diện tích sàn như quạt đứng.</p><h3>Điểm nổi bật</h3><ul><li>5 cánh thiết kế khí động học, lưu lượng gió lớn mà vẫn êm</li><li>Cảm biến nhiệt độ tự tăng giảm tốc độ khi phòng nóng lên hay mát đi</li><li>Remote hẹn giờ và chỉnh nhiều mức gió</li><li>Động cơ 70W bền, ít rung lắc</li></ul><h3>Phù hợp với</h3><p>Phòng khách, phòng thờ, nhà phố trần từ 3 mét.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"control": "Remote", "timer": "Có"}') WHERE product_id = 8;
UPDATE product_details SET description = 'Lọc sạch phòng 48 m² trong khoảng 10 phút, theo dõi chất lượng không khí trên app Mi Home.', content = '<p>Xiaomi Smart Air Purifier 4 có CADR 400 m³/h, vượt trội trong tầm giá. Màn hình hiển thị PM2.5 theo thời gian thực nên bạn biết rõ không khí trong phòng đang thế nào.</p><h3>Điểm nổi bật</h3><ul><li>Bộ lọc 3 lớp: lưới thô, HEPA và than hoạt tính khử mùi</li><li>Chế độ ngủ chỉ 32dB, đặt trong phòng ngủ không bị làm phiền</li><li>App Mi Home báo khi cần thay lõi lọc, hẹn giờ, điều khiển bằng giọng nói</li><li>Tự chuyển tốc độ theo mức bụi đo được</li></ul><h3>Phù hợp với</h3><p>Phòng khách, phòng ngủ lớn, căn hộ gần đường đông xe.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"area": "Đến 48m2", "filter": "HEPA 3 lớp", "connectivity": "Wi‑Fi, Mi Home"}') WHERE product_id = 9;
UPDATE product_details SET description = 'Máy lọc Coway chạy rất êm, chỉ 28dB, lõi lọc dạng hộp thay trong 1 phút.', content = '<p>Coway nổi tiếng với bộ lọc bền và máy chạy êm. Mẫu Cartridge dùng lõi lọc dạng hộp, tháo lắp nhanh không cần dụng cụ, phù hợp phòng ngủ và phòng làm việc.</p><h3>Điểm nổi bật</h3><ul><li>Lọc 4 bước gồm màng lọc thô, lọc khử mùi, HEPA và màng ion</li><li>Độ ồn thấp nhất 28dB, êm hơn tiếng thì thầm</li><li>Đèn báo chất lượng không khí 4 màu dễ nhìn</li><li>Đèn báo thay lõi, không phải tự nhớ ngày thay</li></ul><h3>Phù hợp với</h3><p>Phòng ngủ có trẻ sơ sinh, người ngủ nông, phòng làm việc cần yên tĩnh.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"filter": "HEPA 4 bước"}') WHERE product_id = 10;
UPDATE product_details SET description = 'Camera trong nhà xoay 360°, đàm thoại 2 chiều, xem nhà mọi lúc trên điện thoại.', content = '<p>Ezviz C6N là lựa chọn dễ bắt đầu cho người lần đầu lắp camera. Cắm điện, quét mã QR trên app là xem được hình, không cần đi dây phức tạp.</p><h3>Điểm nổi bật</h3><ul><li>Độ phân giải 1080p, xoay ngang 360° và nghiêng dọc để không có góc chết</li><li>Hồng ngoại nhìn đêm khoảng 10 m, vẫn thấy rõ khi tắt đèn</li><li>Đàm thoại 2 chiều: nói chuyện với người nhà, trẻ nhỏ hay thú cưng từ xa</li><li>Phát hiện chuyển động, gửi cảnh báo kèm ảnh về điện thoại</li></ul><h3>Phù hợp với</h3><p>Trông trẻ, chăm người già, theo dõi thú cưng khi đi làm.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"night_vision": "Hồng ngoại ~10m", "connectivity": "Wi‑Fi 2.4GHz"}') WHERE product_id = 11;
UPDATE product_details SET description = 'Camera ngoài trời chống nước IP66, độ nét 3MP, quay màu cả ban đêm.', content = '<p>Tapo C310 đặt được ở cổng, sân hay bãi xe. Vỏ chống mưa bụi IP66, ảnh 3MP rõ hơn camera 1080p thông thường, đọc được biển số xe ở khoảng cách gần.</p><h3>Điểm nổi bật</h3><ul><li>Chuẩn chống nước IP66, chịu được mưa lớn và nắng gắt</li><li>Nhìn đêm hồng ngoại tới 30 m</li><li>Còi và đèn báo động khi phát hiện người lạ</li><li>Lưu thẻ nhớ MicroSD đến 128GB hoặc dịch vụ đám mây Tapo Care</li></ul><h3>Phù hợp với</h3><p>Nhà phố, cửa hàng, sân vườn cần giám sát ngoài trời.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"waterproof": "IP66", "night_vision": "Hồng ngoại ~30m"}') WHERE product_id = 12;
UPDATE product_details SET description = 'Khoá vân tay Xiaomi 6 cách mở, pin dùng 18 tháng, cảnh báo về điện thoại khi có người cạy cửa.', content = '<p>Xiaomi Smart Door Lock giúp bạn không còn lo quên chìa. Chạm ngón tay là mở, người nhà có mã riêng, và bạn xem được ai ra vào lúc nào ngay trên app.</p><h3>Điểm nổi bật</h3><ul><li>6 cách mở: vân tay, mật mã, thẻ NFC, Bluetooth, chìa cơ và app</li><li>Mật mã ảo: nhập thêm số ngẫu nhiên trước và sau để người đứng cạnh không nhìn trộm được</li><li>Pin AA dùng khoảng 18 tháng, báo trước khi pin yếu</li><li>Cảnh báo cạy phá, nhập sai nhiều lần gửi thẳng về điện thoại</li></ul><h3>Phù hợp với</h3><p>Căn hộ chung cư, nhà có người lớn tuổi hay trẻ nhỏ hay quên chìa.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"connectivity": "Bluetooth, Mi Home", "unlock_time": "Dưới 1 giây"}') WHERE product_id = 13;
UPDATE product_details SET description = 'Khoá điện tử Hafele (Đức) 5 cách mở, phù hợp cửa gỗ cao cấp, bảo hành chính hãng.', content = '<p>Hafele EL9000 dành cho người cần một chiếc khoá bền, hoàn thiện kim loại chắc tay và đồng bộ với nội thất sang trọng. Thương hiệu Đức, hệ thống bảo hành rộng khắp.</p><h3>Điểm nổi bật</h3><ul><li>5 cách mở: vân tay, mã số, thẻ từ, Bluetooth và chìa cơ dự phòng</li><li>Tay nắm và thân khoá kim loại, chịu va đập tốt</li><li>Chế độ khoá kép từ bên trong khi bạn ở nhà ban đêm</li><li>Cổng sạc khẩn cấp bên ngoài khi hết pin</li></ul><h3>Phù hợp với</h3><p>Biệt thự, nhà phố, cửa gỗ chính cần khoá cao cấp.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"door_type": "Cửa gỗ", "connectivity": "Bluetooth"}') WHERE product_id = 14;
UPDATE product_details SET description = 'Bóng Philips Hue 16 triệu màu: đổi ánh sáng theo giờ, theo tâm trạng bằng app hoặc giọng nói.', content = '<p>Philips Hue biến chiếc đèn trần bình thường thành đèn thông minh. Sáng làm việc dùng ánh sáng trắng, tối xem phim chuyển sang ánh vàng dịu, tất cả chỉnh từ điện thoại.</p><h3>Điểm nổi bật</h3><ul><li>16 triệu màu và dải trắng ấm đến trắng lạnh</li><li>Dùng Bluetooth ngay, thêm Hue Bridge để điều khiển từ xa và hẹn lịch</li><li>Tương thích Google Home, Amazon Alexa, Apple Home</li><li>Đui E27 phổ biến, lắp thay bóng cũ không cần đi lại dây</li></ul><h3>Phù hợp với</h3><p>Phòng ngủ, phòng khách, góc làm việc muốn đổi không khí bằng ánh sáng.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"socket": "E27", "connectivity": "Bluetooth, Zigbee"}') WHERE product_id = 15;
UPDATE product_details SET description = 'Dây LED 2 mét đổi màu theo nhạc, cắt nối linh hoạt cho kệ tivi, gầm giường, bàn làm việc.', content = '<p>Yeelight Lightstrip Pro tạo ánh sáng hắt nền mềm mại, khiến góc phòng trông sâu và ấm hơn. Mỗi đoạn LED hiển thị màu riêng nên tạo được hiệu ứng chuyển màu mượt.</p><h3>Điểm nổi bật</h3><ul><li>16 triệu màu, hiệu ứng nhiều màu cùng lúc trên một dải</li><li>Đồng bộ theo nhạc và màn hình khi xem phim, chơi game</li><li>Nối dài thêm đến 10 mét, cắt theo kích thước</li><li>Điều khiển bằng app Yeelight, Google Home, Alexa</li></ul><h3>Phù hợp với</h3><p>Góc gaming, kệ tivi, gầm giường, phòng ngủ trẻ em.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"connectivity": "Wi‑Fi", "extendable": "Đến 10 mét"}') WHERE product_id = 16;
UPDATE product_details SET description = 'Tủ lạnh 236 lít Inverter tiết kiệm điện, ngăn đá trên, vừa cho gia đình 2–4 người.', content = '<p>Samsung 236L có kích thước gọn mà vẫn đủ chỗ cho thực phẩm cả tuần. Máy nén Digital Inverter chạy êm và giữ nhiệt ổn định nên đồ ăn tươi lâu hơn.</p><h3>Điểm nổi bật</h3><ul><li>Máy nén Digital Inverter tiết kiệm điện, chạy êm, bảo hành máy nén dài hạn</li><li>Luồng khí lạnh đa chiều làm lạnh đều mọi ngăn</li><li>Ngăn rau củ giữ ẩm, khay kính chịu lực</li><li>Khử mùi than hoạt tính, tủ không bị ám mùi</li></ul><h3>Phù hợp với</h3><p>Gia đình nhỏ, phòng trọ rộng, căn hộ 1–2 phòng ngủ.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"door": "2 cánh, ngăn đá trên", "energy": "Inverter tiết kiệm điện"}') WHERE product_id = 17;
UPDATE product_details SET description = 'Máy lạnh 1 HP Inverter gas R32 cho phòng dưới 15 m², lọc bụi mịn nanoe™.', content = '<p>Panasonic Inverter 1 HP làm lạnh nhanh và giữ nhiệt độ ổn định, không bật tắt liên tục như máy thường nên tiết kiệm điện rõ rệt khi dùng cả đêm.</p><h3>Điểm nổi bật</h3><ul><li>Công nghệ Inverter giảm hao điện khi chạy lâu</li><li>nanoe™ giúp ức chế vi khuẩn, nấm mốc và khử mùi trong phòng</li><li>Gas R32 làm lạnh hiệu quả, thân thiện môi trường hơn R410A</li><li>Chế độ ngủ tự điều chỉnh nhiệt độ theo giờ, không bị lạnh buốt về sáng</li></ul><h3>Phù hợp với</h3><p>Phòng ngủ, phòng làm việc dưới 15 m².</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"area": "Dưới 15m2", "energy": "Inverter"}') WHERE product_id = 18;
UPDATE product_details SET description = 'Máy sấy 2000W gió mạnh, 3 chế độ nhiệt, có gió mát giữ nếp tóc.', content = '<p>Máy sấy Panasonic 2000W sấy khô tóc dài nhanh, giảm thời gian đứng trước gương mỗi sáng. Chế độ gió mát giúp khoá nếp sau khi tạo kiểu.</p><h3>Điểm nổi bật</h3><ul><li>Công suất 2000W, luồng gió mạnh làm khô nhanh</li><li>3 mức nhiệt và gió mát, chỉnh phù hợp tóc mỏng hay dày</li><li>Đầu tập trung gió để tạo kiểu chính xác</li><li>Tay cầm gập gọn, mang theo khi đi du lịch</li></ul><h3>Phù hợp với</h3><p>Tóc dài, tóc dày, cả gia đình dùng chung.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"foldable": "Có", "cool_shot": "Có"}') WHERE product_id = 19;
UPDATE product_details SET description = 'Cân đo 13 chỉ số cơ thể, đồng bộ app Mi Fit (Zepp Life) để theo dõi tiến trình tập luyện.', content = '<p>Không chỉ đo cân nặng, cân Xiaomi Body Composition Scale 2 còn ước tính mỡ, cơ, nước, xương… giúp bạn thấy rõ tiến bộ khi tập luyện thay vì chỉ nhìn con số trên cân.</p><h3>Điểm nổi bật</h3><ul><li>13 chỉ số: cân nặng, BMI, tỉ lệ mỡ, cơ, nước, xương, mỡ nội tạng, BMR…</li><li>Tự nhận diện tới 16 người dùng trong gia đình</li><li>Đồng bộ Bluetooth 5.0, lưu lịch sử và biểu đồ trên app</li><li>Mặt kính cường lực, cảm biến nhạy từ 50 g</li></ul><h3>Phù hợp với</h3><p>Người tập gym, giảm cân, gia đình muốn theo dõi sức khoẻ hằng ngày.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"metrics": "13 chỉ số", "users": "16 người"}') WHERE product_id = 20;
UPDATE product_details SET description = 'Nồi chiên Tefal 4,2 lít của Pháp, ít dầu, rổ chống dính và rửa được bằng máy.', content = '<p>Tefal 4.2L hợp bữa cơm 2–4 người. Thiết kế gọn, lòng nồi chống dính bền, nấu đều cả món chiên, nướng lẫn hâm bánh.</p><h3>Điểm nổi bật</h3><ul><li>Công suất 1500W, nhiệt độ chỉnh được đến 200°C</li><li>Hẹn giờ 60 phút, tự ngắt khi hết giờ</li><li>Rổ chiên chống dính, tháo ra rửa được bằng máy</li><li>Chân đế chống trượt, vỏ ngoài ít nóng</li></ul><h3>Phù hợp với</h3><p>Gia đình nhỏ, người mới bắt đầu dùng nồi chiên.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"temperature": "Đến 200°C", "timer": "60 phút"}') WHERE product_id = 21;
UPDATE product_details SET description = 'Nồi chiên Lock&Lock 5,2 lít công suất 1800W, nấu nhanh, lòng nồi vuông rộng.', content = '<p>Lock&Lock 5.2L có rổ vuông nên tận dụng tối đa mặt đáy, xếp được nhiều đồ hơn rổ tròn cùng dung tích. Công suất 1800W rút ngắn thời gian nấu.</p><h3>Điểm nổi bật</h3><ul><li>Rổ vuông 5,2 lít, xếp vừa cánh gà, sườn, cá nguyên con cỡ vừa</li><li>Công suất 1800W làm nóng gần như tức thì</li><li>Bảng cảm ứng nhiều chế độ cài sẵn</li><li>Lớp chống dính dễ lau, tay cầm cách nhiệt</li></ul><h3>Phù hợp với</h3><p>Gia đình 3–5 người, người thích nấu nhanh.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"basket": "Rổ vuông", "control": "Cảm ứng"}') WHERE product_id = 22;
UPDATE product_details SET description = 'Lò vi sóng Electrolux 23 lít có nướng, vừa hâm vừa làm được món nướng đơn giản.', content = '<p>Electrolux 23L thêm chức năng nướng bên cạnh vi sóng, nên ngoài hâm và rã đông còn làm được bánh mì nướng, cánh gà nướng nhanh.</p><h3>Điểm nổi bật</h3><ul><li>Vi sóng 800W kết hợp nướng</li><li>Nhiều chương trình nấu tự động theo món</li><li>Rã đông theo trọng lượng</li><li>Khoang lò dễ lau, cửa kính quan sát</li></ul><h3>Phù hợp với</h3><p>Gia đình muốn một lò vừa hâm vừa nướng.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"programs": "Vi sóng + nướng", "control": "Điện tử"}') WHERE product_id = 23;
UPDATE product_details SET description = 'Lò nướng 50 lít 2000W, nướng gà nguyên con, bánh bông lan, pizza cùng lúc 2 khay.', content = '<p>Sanaky 50L có dung tích lớn cho những bữa tiệc gia đình. Đèn trong lò giúp bạn theo dõi món mà không cần mở cửa làm mất nhiệt.</p><h3>Điểm nổi bật</h3><ul><li>Dung tích 50 lít, nướng được 2 khay cùng lúc</li><li>Nhiệt độ chỉnh đến 230°C, hẹn giờ đến 120 phút</li><li>Thanh nhiệt trên dưới chỉnh riêng, bánh chín đều hai mặt</li><li>Xiên quay gà nguyên con đi kèm</li></ul><h3>Phù hợp với</h3><p>Người thích làm bánh, gia đình hay tổ chức tiệc.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"temperature": "Đến 230°C", "timer": "120 phút"}') WHERE product_id = 24;
UPDATE product_details SET description = 'Quạt điều hoà Sunhouse bình 40 lít, làm mát bằng hơi nước cho phòng rộng mà ít tốn điện.', content = '<p>Sunhouse Boss làm mát bằng cách cho gió đi qua tấm làm mát thấm nước, nhiệt độ quanh quạt giảm vài độ, hợp những căn phòng rộng chưa lắp máy lạnh.</p><h3>Điểm nổi bật</h3><ul><li>Bình nước 40 lít, chạy cả ngày không phải châm thêm</li><li>Công suất 120W, tốn điện ít hơn nhiều lần máy lạnh</li><li>Đảo gió tự động, gió thổi xa</li><li>Remote hẹn giờ, bánh xe di chuyển dễ dàng</li></ul><h3>Phù hợp với</h3><p>Phòng khách, cửa hàng, xưởng nhỏ, nhà không lắp được máy lạnh.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"area": "Đến 30m2", "control": "Remote"}') WHERE product_id = 25;
UPDATE product_details SET description = 'Quạt treo tường Senko có remote, gọn tường, giá dưới 500 nghìn.', content = '<p>Senko treo tường giải phóng mặt sàn, phù hợp phòng nhỏ, bếp hay phòng trọ. Remote giúp chỉnh gió mà không phải với tay lên cao.</p><h3>Điểm nổi bật</h3><ul><li>3 tốc độ gió, đảo chiều rộng</li><li>Remote hẹn giờ tắt</li><li>Công suất 47W, tiết kiệm điện</li><li>Thương hiệu Việt, linh kiện thay thế dễ tìm</li></ul><h3>Phù hợp với</h3><p>Phòng trọ, bếp, phòng ngủ nhỏ.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"control": "Remote", "mount": "Treo tường"}') WHERE product_id = 26;
UPDATE product_details SET description = 'Máy lọc Sharp có ion Plasmacluster, khử mùi và lọc bụi cho phòng khoảng 23 m².', content = '<p>Sharp FP-J30E-A kết hợp lọc HEPA với công nghệ ion Plasmacluster, giúp giảm mùi thức ăn, mùi ẩm mốc trong phòng kín.</p><h3>Điểm nổi bật</h3><ul><li>Ion Plasmacluster hỗ trợ khử mùi và giảm vi khuẩn bám bề mặt</li><li>Lọc HEPA giữ bụi mịn, phấn hoa</li><li>Thiết kế gọn, đặt góc phòng ngủ hay bàn làm việc</li><li>3 tốc độ quạt, chế độ ngủ êm</li></ul><h3>Phù hợp với</h3><p>Phòng ngủ, phòng làm việc kín, phòng có mùi ẩm.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"filter": "HEPA + ion Plasmacluster"}') WHERE product_id = 27;
UPDATE product_details SET description = 'Máy lọc Daikin công nghệ Streamer phân huỷ mùi và chất độc hại cho phòng khoảng 21 m².', content = '<p>Daikin MC30VVM-A dùng công nghệ Streamer độc quyền, không chỉ giữ bụi mà còn phân huỷ một phần mùi và chất hữu cơ bay hơi bám trên bộ lọc.</p><h3>Điểm nổi bật</h3><ul><li>Công nghệ Streamer kết hợp lọc HEPA tĩnh điện</li><li>Thiết kế mỏng, đặt sát tường</li><li>Vận hành êm ở chế độ thấp</li><li>Bộ lọc bền, chi phí bảo trì thấp</li></ul><h3>Phù hợp với</h3><p>Phòng ngủ, phòng trẻ em, phòng làm việc nhỏ.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"filter": "HEPA tĩnh điện + Streamer"}') WHERE product_id = 28;
UPDATE product_details SET description = 'Tủ lạnh LG 315 lít ngăn đá dưới, lấy đồ ngăn mát không phải cúi người.', content = '<p>LG Inverter 315L đặt ngăn mát lên trên, ngăn đá xuống dưới. Ngăn mát là nơi bạn mở nhiều nhất, nên thiết kế này giúp thao tác thoải mái hơn.</p><h3>Điểm nổi bật</h3><ul><li>Máy nén Smart Inverter tiết kiệm điện, chạy êm</li><li>Ngăn đá dưới dạng ngăn kéo, dễ sắp xếp</li><li>Luồng khí lạnh đa chiều, làm lạnh đều</li><li>Ngăn rau củ giữ ẩm riêng</li></ul><h3>Phù hợp với</h3><p>Gia đình 3–5 người.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"door": "2 cánh, ngăn đá dưới", "energy": "Inverter"}') WHERE product_id = 29;
UPDATE product_details SET description = 'Tủ lạnh Aqua 189 lít nhỏ gọn, Inverter tiết kiệm, vừa phòng trọ và căn hộ studio.', content = '<p>Aqua 189L có chiều ngang hẹp, đặt vừa những góc bếp nhỏ. Inverter giúp tiền điện hằng tháng thấp dù chạy cả ngày đêm.</p><h3>Điểm nổi bật</h3><ul><li>Máy nén Inverter tiết kiệm điện</li><li>Ngăn đá trên đủ chỗ đá viên và thực phẩm đông lạnh</li><li>Khay kính chịu lực, ngăn cửa đựng chai lớn</li><li>Kích thước gọn, dễ di chuyển khi chuyển nhà</li></ul><h3>Phù hợp với</h3><p>Người ở một mình, cặp đôi, phòng trọ.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"door": "2 cánh, ngăn đá trên", "energy": "Inverter"}') WHERE product_id = 30;
UPDATE product_details SET description = 'Máy lạnh Daikin 1,5 HP Inverter cho phòng 15–20 m², làm lạnh nhanh, êm.', content = '<p>Daikin Inverter 1.5 HP dành cho phòng ngủ lớn hoặc phòng khách nhỏ. Máy giữ nhiệt độ ổn định, chạy êm và tiết kiệm điện khi dùng thường xuyên.</p><h3>Điểm nổi bật</h3><ul><li>Inverter tiết kiệm điện khi chạy liên tục</li><li>Gas R32 làm lạnh hiệu quả</li><li>Chế độ gió dễ chịu, hạn chế thổi thẳng vào người</li><li>Dàn tản nhiệt chống ăn mòn, bền với khí hậu nóng ẩm</li></ul><h3>Phù hợp với</h3><p>Phòng 15–20 m², phòng khách nhỏ.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"area": "15–20m2", "energy": "Inverter"}') WHERE product_id = 31;
UPDATE product_details SET description = 'Máy lạnh LG 1 HP có Wi‑Fi: bật máy trước khi về nhà, theo dõi điện năng trên app.', content = '<p>LG Inverter 1 HP kết nối Wi‑Fi qua app ThinQ. Bạn có thể bật lạnh trước khi về để phòng mát sẵn, hoặc kiểm tra xem đã tắt máy khi ra ngoài chưa.</p><h3>Điểm nổi bật</h3><ul><li>Điều khiển từ xa qua app LG ThinQ</li><li>Dual Inverter tiết kiệm điện, làm lạnh nhanh</li><li>Theo dõi điện năng tiêu thụ theo ngày</li><li>Chế độ ngủ và hẹn giờ</li></ul><h3>Phù hợp với</h3><p>Phòng ngủ dưới 15 m², người hay quên tắt máy lạnh.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"area": "Dưới 15m2", "connectivity": "Wi‑Fi, LG ThinQ"}') WHERE product_id = 32;
UPDATE product_details SET description = 'Camera Imou Ranger 2 giá dễ chịu, xoay 360°, tự bám theo người chuyển động.', content = '<p>Imou Ranger 2 tự xoay theo chuyển động trong khung hình, nên một camera bao quát được cả phòng khách. Thẻ nhớ đến 256GB lưu được nhiều ngày ghi hình.</p><h3>Điểm nổi bật</h3><ul><li>Xoay ngang 355°, nghiêng dọc, tự động bám theo người</li><li>Phát hiện con người, giảm báo động giả do rèm bay hay thú cưng</li><li>Đàm thoại 2 chiều, nhìn đêm hồng ngoại</li><li>Hỗ trợ thẻ nhớ đến 256GB</li></ul><h3>Phù hợp với</h3><p>Phòng khách, cửa hàng nhỏ, trông trẻ.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"night_vision": "Hồng ngoại ~10m", "connectivity": "Wi‑Fi"}') WHERE product_id = 33;
UPDATE product_details SET description = 'Camera ngoài trời KBVision 4MP, hình sắc nét, chịu mưa nắng, lưu thẻ đến 256GB.', content = '<p>KBVision 4MP có độ phân giải cao hơn camera 1080p phổ thông, phóng to vẫn nhìn rõ chi tiết khuôn mặt hay biển số xe ở cổng.</p><h3>Điểm nổi bật</h3><ul><li>Độ phân giải 4MP, hình ảnh rõ khi phóng to</li><li>Vỏ kim loại chống nước, phù hợp lắp ngoài trời</li><li>Nhìn đêm hồng ngoại tầm xa</li><li>Thẻ nhớ đến 256GB, xem lại trên app</li></ul><h3>Phù hợp với</h3><p>Cổng nhà, sân, bãi xe, cửa hàng.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"waterproof": "Chuẩn ngoài trời", "night_vision": "Hồng ngoại tầm xa"}') WHERE product_id = 34;
UPDATE product_details SET description = 'Khoá Samsung SHP-DP738 dạng đẩy kéo: mở bằng vân tay chỉ với một thao tác đẩy tay nắm.', content = '<p>SHP-DP738 có thiết kế tay nắm đẩy kéo, vừa chạm vân tay vừa đẩy cửa trong một động tác, rất tiện khi tay đang xách đồ. Bàn phím chỉ sáng khi chạm vào.</p><h3>Điểm nổi bật</h3><ul><li>Vân tay, mã số, thẻ từ, Bluetooth và chìa cơ</li><li>Tay nắm đẩy kéo, mở cửa một chạm</li><li>Báo động khi có người cạy phá hoặc có nhiệt độ cao bất thường</li><li>Hoàn thiện kim loại, hợp cửa gỗ và cửa thép</li></ul><h3>Phù hợp với</h3><p>Nhà phố, biệt thự, căn hộ cao cấp.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"handle": "Đẩy kéo", "connectivity": "Bluetooth"}') WHERE product_id = 35;
UPDATE product_details SET description = 'Khoá vân tay chuyên cho cửa nhôm Xingfa, thân mỏng, lắp không cần khoét lại cửa.', content = '<p>Kaimi được thiết kế riêng cho khung cửa nhôm Xingfa vốn hẹp. Thân khoá mỏng nên lắp vừa khung, giữ nguyên thẩm mỹ cửa.</p><h3>Điểm nổi bật</h3><ul><li>4 cách mở: vân tay, mã số, thẻ từ và chìa cơ</li><li>Thân khoá mỏng, vừa khung nhôm hệ Xingfa</li><li>Pin dùng khoảng 12 tháng, báo pin yếu</li><li>Chống nước nhẹ, lắp được cửa ban công, cửa sân</li></ul><h3>Phù hợp với</h3><p>Nhà có cửa nhôm Xingfa, cửa ban công, cửa sau.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"door_type": "Cửa nhôm Xingfa"}') WHERE product_id = 36;
UPDATE product_details SET description = 'Bóng đèn Xiaomi Wi‑Fi giá rẻ, 16 triệu màu, ra lệnh bằng giọng nói qua Google Home.', content = '<p>Xiaomi Mi LED Smart Bulb là cách tiết kiệm nhất để bắt đầu với nhà thông minh. Không cần bộ trung tâm, chỉ cần Wi‑Fi và app Mi Home.</p><h3>Điểm nổi bật</h3><ul><li>Kết nối Wi‑Fi trực tiếp, không cần bộ trung tâm</li><li>16 triệu màu, chỉnh độ sáng và nhiệt độ màu</li><li>Hẹn giờ bật tắt, tạo kịch bản sáng dần buổi sáng</li><li>Đui E27 phổ biến</li></ul><h3>Phù hợp với</h3><p>Phòng ngủ, phòng trẻ em, người mới làm quen nhà thông minh.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"socket": "E27", "connectivity": "Wi‑Fi, Mi Home"}') WHERE product_id = 37;
UPDATE product_details SET description = 'Đèn ốp trần Rạng Đông đổi nhiệt độ màu 3000K–6500K, điều khiển bằng app.', content = '<p>Đèn ốp trần Rạng Đông chỉnh được từ vàng ấm đến trắng sáng. Buổi tối chuyển sang ánh vàng dịu để dễ ngủ, ban ngày dùng ánh trắng để làm việc.</p><h3>Điểm nổi bật</h3><ul><li>Nhiệt độ màu 3000K–6500K, chỉnh độ sáng mượt</li><li>Điều khiển qua app và remote</li><li>Ánh sáng không nhấp nháy, dịu mắt</li><li>Thương hiệu Việt, bảo hành dễ dàng</li></ul><h3>Phù hợp với</h3><p>Phòng khách, phòng ngủ, phòng học.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"connectivity": "Wi‑Fi"}') WHERE product_id = 38;
UPDATE product_details SET description = 'Dyson Airwrap uốn, sấy và tạo phồng bằng luồng khí, không dùng nhiệt quá cao làm hư tóc.', content = '<p>Airwrap dùng hiệu ứng Coanda để cuốn tóc quanh đầu uốn bằng luồng khí, nên tạo được lọn xoăn mà không cần kẹp nóng. Một máy thay cho máy sấy, máy uốn và lược điện.</p><h3>Điểm nổi bật</h3><ul><li>Uốn tóc bằng luồng khí, nhiệt độ được kiểm soát để hạn chế hư tổn</li><li>6 đầu phụ kiện: uốn hai chiều, lược tròn, lược dẹt, sấy…</li><li>Dùng được cho nhiều kiểu tóc và độ dài khác nhau</li><li>Hộp đựng sang trọng, phù hợp làm quà tặng</li></ul><h3>Phù hợp với</h3><p>Người tạo kiểu tóc hằng ngày, tóc dễ hư tổn do nhiệt.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"temperature": "Kiểm soát dưới 150°C"}') WHERE product_id = 39;
UPDATE product_details SET description = 'Máy massage cổ Xiaomi Jeeback xung điện kết hợp chườm nóng, dùng 8 ngày mỗi lần sạc.', content = '<p>Jeeback ôm vòng quanh cổ, dùng xung điện tần số thấp kết hợp chườm ấm để thư giãn vùng cổ vai sau giờ ngồi máy tính.</p><h3>Điểm nổi bật</h3><ul><li>4 chế độ massage, nhiều mức cường độ</li><li>Chườm ấm khoảng 38–42°C</li><li>Thiết kế nhẹ, đeo khi đang làm việc hoặc nghỉ ngơi</li><li>Pin dùng khoảng 8 ngày, sạc USB-C</li></ul><h3>Phù hợp với</h3><p>Dân văn phòng, người hay mỏi cổ vai gáy.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"temperature": "38–42°C", "charging": "USB-C"}') WHERE product_id = 40;
UPDATE product_details SET description = 'Roborock S8 Pro Ultra tự hút, tự lau, tự giặt và sấy giẻ, tự đổ rác: gần như không phải đụng tay.', content = '<p>S8 Pro Ultra là robot dành cho người muốn sàn nhà sạch mỗi ngày mà không phải làm gì. Trạm sạc RockDock Ultra lo việc đổ bụi, giặt giẻ, sấy khô và châm nước sạch.</p><h3>Điểm nổi bật</h3><ul><li>Lực hút 6000Pa, hai chổi cao su chống rối tóc</li><li>Giẻ lau rung tần số cao, tự nâng khi gặp thảm</li><li>Trạm sạc tự đổ bụi, giặt và sấy giẻ, châm nước</li><li>Cảm biến LiDAR và camera né vật cản, vẽ bản đồ nhiều tầng</li></ul><h3>Phù hợp với</h3><p>Nhà nhiều phòng, nhà có thú cưng, người bận rộn.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"navigation": "LiDAR + camera né vật cản", "dock": "Tự đổ rác, giặt và sấy giẻ"}') WHERE product_id = 41;
UPDATE product_details SET description = 'Ecovacs Deebot T20 Omni lau nước nóng, tự nâng giẻ trên thảm, trạm sạc tự làm sạch.', content = '<p>Deebot T20 Omni giặt giẻ bằng nước nóng ở trạm sạc, giúp giẻ sạch hơn và hạn chế mùi hôi. Robot tự nâng giẻ khi đi qua thảm để thảm không bị ướt.</p><h3>Điểm nổi bật</h3><ul><li>Lực hút 6000Pa</li><li>Giặt giẻ nước nóng, sấy khí nóng</li><li>Tự nâng giẻ khi gặp thảm</li><li>Trợ lý giọng nói YIKO, điều khiển bằng lời</li></ul><h3>Phù hợp với</h3><p>Nhà có sàn gỗ, sàn gạch xen thảm.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"navigation": "LiDAR", "dock": "Tự đổ rác, giặt giẻ nước nóng"}') WHERE product_id = 42;
UPDATE product_details SET description = 'Robot lau kính Ecovacs Winbot bám dính chắc, lau cửa kính nhà cao tầng an toàn.', content = '<p>Winbot hút chặt vào mặt kính và tự đi theo đường zíc-zắc để lau sạch. Bạn không phải trèo ra ban công hay cửa sổ cao để lau kính nữa.</p><h3>Điểm nổi bật</h3><ul><li>Lực hút chân không giữ robot bám chắc trên kính</li><li>Dây an toàn và pin dự phòng khi mất điện</li><li>Tự tính đường lau, nhận biết khung cửa</li><li>Phun nước tự động, lau ướt và lau khô</li></ul><h3>Phù hợp với</h3><p>Căn hộ cao tầng, nhà nhiều cửa kính, văn phòng.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"safety": "Dây an toàn + pin dự phòng"}') WHERE product_id = 43;
UPDATE product_details SET description = 'Dyson V15 Detect chiếu laser làm lộ bụi mịn trên sàn và đếm hạt bụi theo thời gian thực.', content = '<p>V15 Detect cho bạn thấy chính xác chỗ nào còn bụi: đầu hút chiếu tia laser làm nổi bụi vô hình, màn hình LCD hiển thị kích thước và số lượng hạt bụi vừa hút.</p><h3>Điểm nổi bật</h3><ul><li>Lực hút 240AW, tự tăng lực khi gặp vùng nhiều bụi</li><li>Đầu laser làm lộ bụi mịn trên sàn cứng</li><li>Màn hình LCD hiển thị lượng bụi, thời gian pin còn lại</li><li>Pin đến 60 phút ở chế độ tiêu chuẩn, có thể thay pin</li></ul><h3>Phù hợp với</h3><p>Nhà có thú cưng, người dị ứng bụi, nhà sàn cứng.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"filter": "HEPA toàn máy", "display": "LCD"}') WHERE product_id = 44;
UPDATE product_details SET description = 'Máy hút bụi cầm tay Xiaomi G11 lực hút 185AW, pin 60 phút, giá chưa tới một phần ba Dyson.', content = '<p>Xiaomi G11 có lực hút mạnh trong tầm giá, pin đủ hút cả căn hộ trong một lần sạc. Màn hình hiển thị chế độ và thời lượng pin còn lại.</p><h3>Điểm nổi bật</h3><ul><li>Lực hút 185AW, 3 chế độ</li><li>Pin đến 60 phút ở chế độ thấp</li><li>Màn hình LED hiển thị thông tin</li><li>Nhiều đầu hút cho sàn, nệm, khe hẹp</li></ul><h3>Phù hợp với</h3><p>Căn hộ 2–3 phòng ngủ, người cần máy hút gọn nhẹ.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"display": "LED", "filter": "HEPA"}') WHERE product_id = 45;
UPDATE product_details SET description = 'Smart TV Samsung 4K 65 inch, màu sắc rực rỡ, hệ điều hành Tizen nhiều ứng dụng.', content = '<p>Màn hình 65 inch tạo trải nghiệm như rạp phim tại nhà. Bộ xử lý 4K nâng cấp hình ảnh độ phân giải thấp lên gần 4K.</p><h3>Điểm nổi bật</h3><ul><li>Độ phân giải 4K UHD, hỗ trợ HDR</li><li>Hệ điều hành Tizen: YouTube, Netflix, FPT Play…</li><li>Điều khiển giọng nói, chiếu màn hình điện thoại</li><li>Chế độ game giảm độ trễ</li></ul><h3>Phù hợp với</h3><p>Phòng khách rộng từ 20 m², gia đình thích xem phim, thể thao.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"os": "Tizen", "hdr": "HDR10+"}') WHERE product_id = 46;
UPDATE product_details SET description = 'Google TV Sony 4K 55 inch, hình ảnh tự nhiên, tìm phim bằng giọng nói tiếng Việt.', content = '<p>Sony 4K 55 inch nổi bật với màu da tự nhiên và chuyển động mượt. Google TV gom phim từ nhiều ứng dụng vào một giao diện, tìm bằng giọng nói tiếng Việt.</p><h3>Điểm nổi bật</h3><ul><li>Bộ xử lý 4K HDR Processor X1</li><li>Google TV, Chromecast tích hợp</li><li>Âm thanh Dolby Audio</li><li>Tìm kiếm bằng giọng nói tiếng Việt</li></ul><h3>Phù hợp với</h3><p>Phòng khách 15–25 m².</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"os": "Google TV", "hdr": "HDR10, HLG"}') WHERE product_id = 47;
UPDATE product_details SET description = 'LG OLED 55 inch: màu đen tuyệt đối, tương phản vô cực, xem phim tối cực kỳ ấn tượng.', content = '<p>Trên TV OLED, mỗi điểm ảnh tự phát sáng và tắt hẳn khi hiển thị màu đen, nên cảnh tối có chiều sâu mà TV LED không đạt được.</p><h3>Điểm nổi bật</h3><ul><li>Tấm nền OLED tự phát sáng, màu đen thật</li><li>Dolby Vision và Dolby Atmos</li><li>Hỗ trợ 120Hz, G-Sync/FreeSync cho game</li><li>webOS, Magic Remote trỏ chuột</li></ul><h3>Phù hợp với</h3><p>Người mê phim, game thủ, phòng có thể giảm sáng.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"os": "webOS", "hdr": "Dolby Vision"}') WHERE product_id = 48;
UPDATE product_details SET description = 'Soundbar Samsung 3.1.2 kênh có loa hướng trần, âm thanh vòm Dolby Atmos.', content = '<p>HW-Q600B có loa hướng lên trần tạo âm thanh theo chiều cao, nghe tiếng mưa hay trực thăng như ở trên đầu. Loa siêu trầm không dây đặt đâu cũng được.</p><h3>Điểm nổi bật</h3><ul><li>3.1.2 kênh, công suất 360W</li><li>Dolby Atmos và DTS:X</li><li>Loa siêu trầm không dây</li><li>Kết nối HDMI eARC, Bluetooth</li></ul><h3>Phù hợp với</h3><p>Phòng khách, người xem phim hành động.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"connectivity": "HDMI eARC, Bluetooth"}') WHERE product_id = 49;
UPDATE product_details SET description = 'Soundbar Sony 2.1 kênh 330W, loa siêu trầm không dây, nâng giọng thoại rõ hơn.', content = '<p>HT-S400 giúp lời thoại phim rõ hơn hẳn loa tivi, không phải tăng âm lượng quá lớn. Loa siêu trầm không dây cho tiếng bass chắc.</p><h3>Điểm nổi bật</h3><ul><li>2.1 kênh, công suất 330W</li><li>Loa siêu trầm không dây</li><li>S-Force Pro Front Surround giả lập âm thanh vòm</li><li>Kết nối HDMI ARC, quang, Bluetooth</li></ul><h3>Phù hợp với</h3><p>Phòng khách vừa, người muốn nâng cấp âm thanh tivi.</p>', specifications = JSON_MERGE_PATCH(COALESCE(specifications, JSON_OBJECT()), '{"connectivity": "HDMI ARC, Optical, Bluetooth"}') WHERE product_id = 50;
